import type { BankQuestion } from "@/lib/bank";

/** Chemical Thermodynamics (Chemistry (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-thermodynamics-1","question":"Which of the following is a state function?","options":["Work done by the system","Heat absorbed by the system","Internal energy of the system","Both work and heat"],"answer":2,"explanation":"Internal energy (like H, S, G, T, P, V) depends only on the state of the system. Heat and work are path functions: their values depend on how the change is carried out.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-2","question":"For the isothermal expansion of an ideal gas, the change in internal energy ΔU is:","options":["Positive","Negative","Zero","Positive or negative depending on the pressure"],"answer":2,"explanation":"The internal energy of an ideal gas depends only on temperature. At constant temperature ΔU = 0, so the heat absorbed equals the work done by the gas (q = −w).","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-3","question":"The standard enthalpy of formation is zero for which of the following at 298 K?","options":["O₃(g)","C(diamond)","Br₂(l)","Cl(g)"],"answer":2,"explanation":"ΔfH° is zero only for an element in its most stable (reference) state: Br₂(l), O₂(g), C(graphite), Cl₂(g). Ozone, diamond and atomic chlorine are not reference states.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-4","question":"For the reaction N₂(g) + 3H₂(g) → 2NH₃(g) at 300 K, the value of ΔH − ΔU is (R = 8.314 J K⁻¹ mol⁻¹):","options":["−4.99 kJ","+4.99 kJ","−2.49 kJ","0"],"answer":0,"explanation":"ΔH − ΔU = Δn(g)RT. Δn(g) = 2 − (1 + 3) = −2, so ΔH − ΔU = −2 × 8.314 × 300 = −4988 J ≈ −4.99 kJ. The sign is negative because the number of gas moles falls.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-5","question":"One mole of an ideal gas expands isothermally and reversibly from 10 L to 100 L at 300 K. The work done is (R = 8.314 J K⁻¹ mol⁻¹):","options":["−2.49 kJ","−574 J","+5.74 kJ","−5.74 kJ"],"answer":3,"explanation":"w = −nRT ln(V₂/V₁) = −1 × 8.314 × 300 × 2.303 × log 10 = −5744 J ≈ −5.74 kJ. Work is negative because the gas does work on the surroundings.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-6","question":"The enthalpy of fusion of ice is 6.0 kJ mol⁻¹. The entropy change when 1 mol of ice melts at 0 °C is approximately:","options":["22 J K⁻¹ mol⁻¹","0.022 J K⁻¹ mol⁻¹","6.0 J K⁻¹ mol⁻¹","273 J K⁻¹ mol⁻¹"],"answer":0,"explanation":"For a phase change at equilibrium ΔS = ΔH/T = 6000 J / 273 K ≈ 22 J K⁻¹ mol⁻¹. Remember to convert kJ to J and °C to K.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-7","question":"A reaction is spontaneous at all temperatures when:","options":["ΔH > 0 and ΔS > 0","ΔH < 0 and ΔS < 0","ΔH < 0 and ΔS > 0","ΔH > 0 and ΔS < 0"],"answer":2,"explanation":"ΔG = ΔH − TΔS. With ΔH negative and ΔS positive, ΔG is negative at every temperature. ΔH > 0, ΔS > 0 is spontaneous only at high T; ΔH < 0, ΔS < 0 only at low T.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-8","question":"Given bond enthalpies H–H = 436, Cl–Cl = 242 and H–Cl = 431 kJ mol⁻¹, the enthalpy change for H₂(g) + Cl₂(g) → 2HCl(g) is:","options":["+184 kJ","−92 kJ","−184 kJ","−247 kJ"],"answer":2,"explanation":"ΔH = Σ(bonds broken) − Σ(bonds formed) = (436 + 242) − 2 × 431 = 678 − 862 = −184 kJ. The option −92 kJ is the value per mole of HCl, not for the equation as written.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-9","question":"Given C(s) + O₂(g) → CO₂(g), ΔH = −393.5 kJ and CO(g) + ½O₂(g) → CO₂(g), ΔH = −283.0 kJ, the enthalpy of formation of CO(g) is:","options":["+110.5 kJ mol⁻¹","−283.0 kJ mol⁻¹","−676.5 kJ mol⁻¹","−110.5 kJ mol⁻¹"],"answer":3,"explanation":"By Hess's law, subtract the second equation from the first: C(s) + ½O₂(g) → CO(g), ΔH = −393.5 − (−283.0) = −110.5 kJ mol⁻¹. Adding the two values (−676.5) is the common error.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-10","question":"One mole of a monoatomic ideal gas at 300 K expands adiabatically and reversibly until its volume doubles. The final temperature is approximately (∛4 ≈ 1.587):","options":["300 K","227 K","189 K","150 K"],"answer":2,"explanation":"For a reversible adiabatic process T × V to the power (γ − 1) is constant, with γ = 5/3 for a monoatomic gas. T₂ = 300 × (1/2) to the power 2/3 = 300/∛4 = 300/1.587 ≈ 189 K. 227 K would be the answer for a diatomic gas (γ = 1.4).","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-11","question":"The equilibrium constant of a reaction is 100 at 298 K. Its standard Gibbs energy change ΔG° is (R = 8.314 J K⁻¹ mol⁻¹):","options":["+11.4 kJ mol⁻¹","−22.8 kJ mol⁻¹","−5.7 kJ mol⁻¹","−11.4 kJ mol⁻¹"],"answer":3,"explanation":"ΔG° = −2.303 RT log K = −2.303 × 8.314 × 298 × log 100 = −5706 × 2 = −11412 J ≈ −11.4 kJ mol⁻¹. K > 1 means ΔG° is negative.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-12","question":"For a reaction ΔH = +40 kJ mol⁻¹ and ΔS = +100 J K⁻¹ mol⁻¹ (both assumed constant). The reaction is spontaneous:","options":["Below 400 K","Above 400 K","At every temperature","At no temperature"],"answer":1,"explanation":"ΔG = ΔH − TΔS < 0 requires T > ΔH/ΔS = 40000/100 = 400 K. An endothermic reaction with positive ΔS becomes spontaneous only above the crossover temperature; mind the kJ/J unit conversion.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-13","question":"Combustion of benzene, C₆H₆(l) + 7.5O₂(g) → 6CO₂(g) + 3H₂O(l), gives ΔU = −3263 kJ mol⁻¹ at 298 K in a bomb calorimeter. ΔH for the reaction is (RT ≈ 2.48 kJ mol⁻¹):","options":["−3259.3 kJ mol⁻¹","−3266.7 kJ mol⁻¹","−3263.0 kJ mol⁻¹","−3270.4 kJ mol⁻¹"],"answer":1,"explanation":"ΔH = ΔU + Δn(g)RT, with Δn(g) = 6 − 7.5 = −1.5 (water is liquid, so it is not counted). ΔH = −3263 + (−1.5 × 2.48) = −3263 − 3.72 ≈ −3266.7 kJ mol⁻¹.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-14","question":"The enthalpy of neutralisation of a strong acid with a strong base is −57.1 kJ mol⁻¹, while that of HCN with NaOH is −12.1 kJ mol⁻¹. The enthalpy of ionisation of HCN is:","options":["+45.0 kJ mol⁻¹","−69.2 kJ mol⁻¹","−45.0 kJ mol⁻¹","+69.2 kJ mol⁻¹"],"answer":0,"explanation":"For a weak acid, observed ΔH(neut) = ΔH(ionisation) + (−57.1). So ΔH(ionisation) = −12.1 − (−57.1) = +45.0 kJ mol⁻¹: part of the released heat is used to ionise the weak acid.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-15","question":"Two moles of an ideal gas expand isothermally and reversibly from 1 atm to 0.1 atm at 300 K. The entropy change of the gas is (R = 8.314 J K⁻¹ mol⁻¹):","options":["19.1 J K⁻¹","0","38.3 J K⁻¹","−38.3 J K⁻¹"],"answer":2,"explanation":"ΔS = nR ln(P₁/P₂) = 2 × 8.314 × 2.303 × log 10 = 38.3 J K⁻¹. Entropy of the gas rises on expansion; ΔS is not zero even though ΔU = 0 for an isothermal ideal-gas process.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-16","question":"Born–Haber data for NaCl: ΔfH°(NaCl) = −411, sublimation of Na = +108, ionisation of Na = +496, ½ dissociation of Cl₂ = +121, electron gain of Cl = −349 (all kJ mol⁻¹). The lattice enthalpy (Na⁺(g) + Cl⁻(g) → NaCl(s)) is:","options":["−787 kJ mol⁻¹","+376 kJ mol⁻¹","−411 kJ mol⁻¹","−1163 kJ mol⁻¹"],"answer":0,"explanation":"ΔfH° = sublimation + ionisation + ½ dissociation + electron gain + lattice enthalpy. −411 = 108 + 496 + 121 − 349 + L = 376 + L, so L = −787 kJ mol⁻¹.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-17","question":"Two moles of a monoatomic ideal gas are heated from 300 K to 400 K at constant pressure. The heat absorbed (q) and the change in internal energy (ΔU) are (R = 8.314 J K⁻¹ mol⁻¹):","options":["q = 2.49 kJ, ΔU = 4.16 kJ","q = 4.16 kJ, ΔU = 4.16 kJ","q = 2.49 kJ, ΔU = 2.49 kJ","q = 4.16 kJ, ΔU = 2.49 kJ"],"answer":3,"explanation":"At constant pressure q = nCpΔT = 2 × (5/2)R × 100 = 4157 J ≈ 4.16 kJ, while ΔU = nCvΔT = 2 × (3/2)R × 100 = 2494 J ≈ 2.49 kJ. The difference (1.66 kJ) is the expansion work done by the gas.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-18","question":"The enthalpy of hydrogenation of cyclohexene is −119 kJ mol⁻¹ and that of benzene is −208 kJ mol⁻¹. The resonance energy of benzene is approximately:","options":["238 kJ mol⁻¹","327 kJ mol⁻¹","89 kJ mol⁻¹","149 kJ mol⁻¹"],"answer":3,"explanation":"A hypothetical cyclohexatriene with three isolated C=C would release 3 × 119 = 357 kJ mol⁻¹. Benzene releases only 208 kJ mol⁻¹, so it is stabilised by 357 − 208 = 149 kJ mol⁻¹ (resonance energy ≈ −149 kJ mol⁻¹).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-19","question":"How many of the following statements are correct? (i) For a spontaneous process ΔS(universe) > 0. (ii) For any process between the same two states, the work done in a reversible expansion is smaller in magnitude than in an irreversible expansion. (iii) At equilibrium at constant T and P, ΔG = 0. (iv) The entropy of a perfectly crystalline substance is zero at 0 K.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(i), (iii) and (iv) are correct. (ii) is wrong: reversible expansion does the maximum work, so its magnitude is larger, not smaller, than that of an irreversible expansion between the same states.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-20","question":"For N₂O₄(g) ⇌ 2NO₂(g), ΔG° = +5.7 kJ mol⁻¹ at 298 K. The equilibrium constant Kp is closest to (2.303 RT ≈ 5.7 kJ mol⁻¹):","options":["10","1.0","0.1","0.01"],"answer":2,"explanation":"ΔG° = −2.303 RT log K gives log K = −5.7/5.7 = −1, so K = 10⁻¹ = 0.1. A positive ΔG° means K < 1, which rules out 10 and 1.0.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-21","question":"A reaction has ΔH = −100 kJ and ΔS(system) = −200 J K⁻¹ at 300 K. The total entropy change (system + surroundings) is:","options":["+133 J K⁻¹","−533 J K⁻¹","−133 J K⁻¹","+533 J K⁻¹"],"answer":0,"explanation":"ΔS(surr) = −ΔH/T = +100000/300 = +333 J K⁻¹. ΔS(total) = −200 + 333 = +133 J K⁻¹ > 0, so the reaction is spontaneous despite the negative ΔS of the system (equivalently ΔG = −100 + 300 × 0.2 = −40 kJ).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-22","question":"Assertion (A): Mixing of two ideal gases at the same temperature and pressure is spontaneous even though ΔH(mix) = 0. Reason (R): ΔS(mix) is positive, so ΔG(mix) = −TΔS(mix) is negative.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Ideal gases do not interact, so ΔH = 0; the driving force is the increase in entropy of mixing. ΔG = ΔH − TΔS = −TΔS < 0, so R correctly explains A.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-thermodynamics-23","question":"Match the process with the correct description. (A) Free expansion of an ideal gas into vacuum at constant T; (B) Reversible adiabatic compression; (C) Condensation of steam at 100 °C and 1 atm; (D) Melting of ice at 0 °C and 1 atm. (p) ΔS(sys) = 0; (q) ΔS(sys) > 0, q = 0, w = 0; (r) ΔS(sys) < 0, ΔG = 0; (s) ΔS(sys) > 0, ΔG = 0.","options":["A–p, B–q, C–r, D–s","A–q, B–p, C–r, D–s","A–q, B–p, C–s, D–r","A–s, B–p, C–r, D–q"],"answer":1,"explanation":"Free expansion: no work (P(ext) = 0), no heat, but the gas's entropy rises (q). Reversible adiabatic: q(rev) = 0 so ΔS = 0 (p). Condensation at the normal b.p. is a phase equilibrium (ΔG = 0) with entropy decreasing (r); melting at 0 °C is also ΔG = 0 but ΔS > 0 (s).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-24","question":"Enthalpies of combustion of C(graphite), H₂(g) and C₂H₆(g) are −393.5, −285.8 and −1560 kJ mol⁻¹ respectively. The enthalpy of formation of ethane is:","options":["−1644.4 kJ mol⁻¹","−2644.4 kJ mol⁻¹","+84.4 kJ mol⁻¹","−84.4 kJ mol⁻¹"],"answer":3,"explanation":"ΔfH(C₂H₆) = 2ΔcH(C) + 3ΔcH(H₂) − ΔcH(C₂H₆) = 2(−393.5) + 3(−285.8) − (−1560) = −787.0 − 857.4 + 1560 = −84.4 kJ mol⁻¹. Forgetting to multiply H₂ by 3 or subtracting in the wrong order gives the distractors.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-25","question":"A reaction has ΔG° = −20 kJ mol⁻¹ at 300 K. When the reaction quotient Q = 10⁴, the value of ΔG and the direction of spontaneous change are (2.303 RT ≈ 5.74 kJ mol⁻¹):","options":["−43.0 kJ mol⁻¹; forward direction is spontaneous","+3.0 kJ mol⁻¹; reverse direction is spontaneous","−3.0 kJ mol⁻¹; forward direction is spontaneous","+43.0 kJ mol⁻¹; reverse direction is spontaneous"],"answer":1,"explanation":"ΔG = ΔG° + 2.303 RT log Q = −20 + 5.74 × 4 = −20 + 22.96 ≈ +3.0 kJ mol⁻¹. A positive ΔG means the reaction as written is non-spontaneous; it proceeds in reverse until Q falls to K (log K = 20/5.74 ≈ 3.5).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-26","question":"ΔfH°(CH₄, g) = −75 kJ mol⁻¹, enthalpy of sublimation of C(graphite) = +717 kJ mol⁻¹ and bond enthalpy of H₂ = 436 kJ mol⁻¹. The mean C–H bond enthalpy in methane is:","options":["364 kJ mol⁻¹","1664 kJ mol⁻¹","304 kJ mol⁻¹","416 kJ mol⁻¹"],"answer":3,"explanation":"C(g) + 4H(g) → CH₄(g): ΔH = ΔfH(CH₄) − [ΔH(sub) + 2 × 436] = −75 − (717 + 872) = −1664 kJ mol⁻¹ for four bonds. Mean C–H bond enthalpy = 1664/4 = 416 kJ mol⁻¹. Using only one mole of H₂ (436, not 872) gives the wrong 304.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-27","question":"A gas expands from 5 L to 15 L against a constant external pressure of 2 atm while absorbing 1200 J of heat. The change in internal energy is (1 L atm = 101.3 J):","options":["+3226 J","−826 J","+826 J","−3226 J"],"answer":1,"explanation":"w = −P(ext)ΔV = −2 × 10 L atm = −20 L atm = −2026 J. ΔU = q + w = 1200 − 2026 = −826 J. The gas loses more energy as work than it gains as heat.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-28","question":"How many of the following statements are correct? (i) ΔS of the system is zero for a reversible adiabatic process. (ii) The entropy of the universe increases in every irreversible process. (iii) For an ideal gas, ΔS for an irreversible isothermal expansion is less than for a reversible isothermal expansion between the same initial and final states. (iv) The standard molar entropy of every substance is zero at 298 K.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(i) and (ii) are correct. (iii) is wrong: S is a state function, so ΔS(system) is the same for both paths (only ΔS(surroundings) differs). (iv) is wrong: S° is zero only for a perfect crystal at 0 K; at 298 K it is positive.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-29","question":"Which neutralisation releases the largest amount of heat per mole of water formed?","options":["HF + NaOH","HCl + NH₄OH","HCl + NaOH","CH₃COOH + NaOH"],"answer":0,"explanation":"Weak acids and bases (CH₃COOH, NH₄OH) release less than 57.1 kJ mol⁻¹ because part of the heat is used for ionisation. HF is the exception: its neutralisation releases about 68 kJ mol⁻¹, more than a strong acid, because the small F⁻ ion is hydrated very exothermically.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-30","question":"For water, ΔH(vap) = 40.7 kJ mol⁻¹ and ΔS(vap) = 109 J K⁻¹ mol⁻¹ (assume constant). At 350 K and 1 atm, ΔG for H₂O(l) → H₂O(g) and the stable phase are:","options":["−2.55 kJ mol⁻¹; vapour is stable","+2.55 kJ mol⁻¹; liquid is stable","0; liquid and vapour are in equilibrium","+40.7 kJ mol⁻¹; liquid is stable"],"answer":1,"explanation":"ΔG = ΔH − TΔS = 40700 − 350 × 109 = 40700 − 38150 = +2550 J ≈ +2.55 kJ mol⁻¹. Vaporisation is non-spontaneous below the boiling point (ΔH/ΔS = 373 K), so liquid water is the stable phase at 350 K.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-31","question":"Which of the following is an extensive property?","options":["Pressure","Density","Temperature","Volume"],"answer":3,"explanation":"Extensive properties depend on the amount of matter (volume, mass, enthalpy). Temperature, density and pressure are intensive.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-32","question":"A gas expands from 1 L to 5 L against a constant external pressure of 1 atm. The work done by the system is (1 L atm = 101.3 J):","options":["w = 0","w = +405.2 J","w = −405.2 J","w = −101.3 J"],"answer":2,"explanation":"w = −P(ext)ΔV = −1 × (5 − 1) = −4 L atm = −405.2 J. The negative sign means work is done by the gas.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-33","question":"For which of the following processes is ΔS of the system negative?","options":["Freezing of water","Melting of ice","Dissolving NaCl in water","Evaporation of water"],"answer":0,"explanation":"Liquid → solid makes the system more ordered, so ΔS < 0. The other processes increase disorder.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-34","question":"The enthalpy of combustion of methane is −890 kJ mol⁻¹. The heat released on complete combustion of 4 g of methane is:","options":["890 kJ","3560 kJ","445 kJ","222.5 kJ"],"answer":3,"explanation":"4 g CH₄ = 0.25 mol; heat = 0.25 × 890 = 222.5 kJ.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-35","question":"For an ideal diatomic gas at ordinary temperatures (vibrations not excited), the ratio Cp/Cv is:","options":["9/7","5/3","4/3","7/5"],"answer":3,"explanation":"Cv = (5/2)R (3 translational + 2 rotational degrees), Cp = Cv + R = (7/2)R, so γ = 7/5 = 1.4. 5/3 is for a monoatomic gas.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-36","question":"A reaction at 300 K has ΔH = −60 kJ. The entropy change of the surroundings is:","options":["−200 J K⁻¹","−0.2 J K⁻¹","+200 J K⁻¹","+20 J K⁻¹"],"answer":2,"explanation":"ΔS(surr) = −ΔH(sys)/T = 60 000/300 = +200 J K⁻¹: heat released into the surroundings raises their entropy.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-37","question":"The standard enthalpies of combustion of graphite and diamond are −393.5 and −395.4 kJ mol⁻¹. The enthalpy change for C(graphite) → C(diamond) is:","options":["−1.9 kJ mol⁻¹","+1.9 kJ mol⁻¹","−788.9 kJ mol⁻¹","+788.9 kJ mol⁻¹"],"answer":1,"explanation":"By Hess's law, ΔH = ΔcH(graphite) − ΔcH(diamond) = −393.5 − (−395.4) = +1.9 kJ mol⁻¹; graphite is the more stable form.","difficulty":"hard","source":"NEET"},
  {"id":"chem-thermodynamics-38","question":"The enthalpy of atomisation of ethane (C₂H₆) is 2826 kJ mol⁻¹ and the average C–H bond enthalpy is 415 kJ mol⁻¹. The C–C bond enthalpy is:","options":["336 kJ mol⁻¹","346 kJ mol⁻¹","2411 kJ mol⁻¹","415 kJ mol⁻¹"],"answer":0,"explanation":"Atomisation breaks 6 C–H and 1 C–C bond: C–C = 2826 − 6 × 415 = 2826 − 2490 = 336 kJ mol⁻¹.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-39","question":"How many of the following statements are correct? (A) Heat capacity is an extensive property, whereas specific heat capacity is intensive. (B) For a reversible process the total entropy change of system plus surroundings is zero. (C) The entropy of a perfectly crystalline substance at 0 K is zero. (D) For the melting of ice at 273 K and 1 atm, ΔG = 0.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct: (B) a reversible process creates no entropy, (C) is the third law, and (D) the two phases are in equilibrium at the normal melting point.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-40","question":"One mole of a monoatomic ideal gas at 300 K and 10 atm expands adiabatically against a constant external pressure of 1 atm until its pressure is 1 atm. The final temperature is:","options":["119 K","300 K","192 K","240 K"],"answer":2,"explanation":"q = 0, so nCvΔT = −P(ext)(V₂ − V₁): 1.5R(T₂ − 300) = −1 × (RT₂/1 − 300R/10). 1.5T₂ − 450 = −T₂ + 30, so T₂ = 480/2.5 = 192 K. 119 K is the reversible-adiabatic answer.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-41","question":"For N₂(g) + 3H₂(g) → 2NH₃(g), ΔH = −92 kJ and ΔS = −199 J K⁻¹ (assume both constant). The reaction stops being spontaneous above about:","options":["298 K","216 K","925 K","462 K"],"answer":3,"explanation":"ΔG = ΔH − TΔS changes sign at T = ΔH/ΔS = 92 000/199 ≈ 462 K. Both terms are negative, so the reaction is spontaneous only below this temperature.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-42","question":"1 g of graphite is burnt completely in a bomb calorimeter of heat capacity 10 kJ K⁻¹, and the temperature rises by 3.2 K. The molar enthalpy of combustion of graphite from these data is:","options":["−32 kJ mol⁻¹","−384 kJ mol⁻¹","−3.2 kJ mol⁻¹","+384 kJ mol⁻¹"],"answer":1,"explanation":"q = 10 × 3.2 = 32 kJ per g, so ΔU = −32 × 12 = −384 kJ mol⁻¹. For C(s) + O₂(g) → CO₂(g), Δn(gas) = 0, so ΔH = ΔU = −384 kJ mol⁻¹.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-43","question":"Assertion (A): The entropy of an ideal gas increases in an isothermal free expansion into vacuum, even though q = 0. Reason (R): ΔS must be calculated along a reversible path between the same initial and final states, and for that path q(rev) > 0.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true: entropy is a state function, so ΔS = nR ln(V₂/V₁) > 0, obtained from the reversible isothermal path, not from the actual q = 0.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-thermodynamics-44","question":"For NaCl, the lattice enthalpy is +788 kJ mol⁻¹ and the hydration enthalpy of its ions is −784 kJ mol⁻¹. The enthalpy of solution and what happens to the temperature on dissolving are:","options":["−1572 kJ mol⁻¹; the solution warms strongly","+4 kJ mol⁻¹; the solution cools slightly","+1572 kJ mol⁻¹; the solution cools strongly","−4 kJ mol⁻¹; the solution warms slightly"],"answer":1,"explanation":"ΔsolH = ΔlatticeH + ΔhydH = 788 − 784 = +4 kJ mol⁻¹. It is slightly endothermic, so the solution cools a little; NaCl still dissolves because ΔS is positive.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-45","question":"1 mol of liquid water is heated from 300 K to 330 K at constant pressure (Cp = 75.3 J K⁻¹ mol⁻¹, ln 1.1 = 0.0953). Its entropy change is about:","options":["7.18 J K⁻¹","75.3 J K⁻¹","2.26 J K⁻¹","0.75 J K⁻¹"],"answer":0,"explanation":"ΔS = nCp ln(T₂/T₁) = 75.3 × ln(330/300) = 75.3 × 0.0953 = 7.18 J K⁻¹. The temperature changes, so q/T with a single T is not exact; 75.3 J K⁻¹ forgets the logarithm.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-thermodynamics-46", "question": "A system that can exchange neither energy nor matter with its surroundings is called:", "options": ["An open system", "A closed system", "An adiabatic open system", "An isolated system"], "answer": 3, "explanation": "An isolated system exchanges neither energy nor matter (an ideal sealed thermos flask). A closed system exchanges energy but not matter; an open system exchanges both.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-thermodynamics-47", "question": "With the IUPAC sign convention (work done on the system is positive), the first law of thermodynamics is written as:", "options": ["ΔU = q − w", "ΔU = q + w", "ΔU = w − q", "ΔU = q × w"], "answer": 1, "explanation": "Heat absorbed (q) and work done on the system (w) both raise the internal energy, so ΔU = q + w. The form q − w belongs to the older convention in which w is work done by the system.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-thermodynamics-48", "question": "For one mole of an ideal gas, Cp − Cv equals:", "options": ["0", "R/2", "R", "2R"], "answer": 2, "explanation": "At constant pressure extra heat is needed to do expansion work; for an ideal gas this extra amount per mole per kelvin is R, so Cp − Cv = R (Mayer's relation).", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-thermodynamics-49", "question": "Given ΔfH°: CO₂(g) = −393.5, H₂O(l) = −285.8 and CH₄(g) = −74.8 kJ mol⁻¹, the standard enthalpy of combustion of methane is:", "options": ["−604.5 kJ mol⁻¹", "−890.3 kJ mol⁻¹", "−1039.9 kJ mol⁻¹", "−754.7 kJ mol⁻¹"], "answer": 1, "explanation": "CH₄ + 2O₂ → CO₂ + 2H₂O(l). ΔH = [−393.5 + 2(−285.8)] − (−74.8) = −965.1 + 74.8 = −890.3 kJ mol⁻¹. −604.5 forgets the coefficient 2 for water; −1039.9 subtracts CH₄ with the wrong sign.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-50", "question": "A reaction is spontaneous only at low temperatures and becomes non-spontaneous at high temperatures. The signs of ΔH and ΔS are:", "options": ["ΔH > 0, ΔS > 0", "ΔH < 0, ΔS > 0", "ΔH > 0, ΔS < 0", "ΔH < 0, ΔS < 0"], "answer": 3, "explanation": "ΔG = ΔH − TΔS. With ΔH < 0 and ΔS < 0, ΔG is negative while |ΔH| > T|ΔS| (low T) and turns positive at high T. ΔH > 0, ΔS > 0 gives the opposite behaviour (spontaneous only at high T).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-51", "question": "At a given temperature, the enthalpy of sublimation of a substance is related to its enthalpies of fusion and vaporisation by:", "options": ["ΔsubH = ΔfusH + ΔvapH", "ΔsubH = ΔvapH − ΔfusH", "ΔsubH = ΔfusH × ΔvapH", "ΔsubH = ΔfusH − ΔvapH"], "answer": 0, "explanation": "Solid → gas can be done as solid → liquid → gas; by Hess's law the enthalpy changes add: ΔsubH = ΔfusH + ΔvapH.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-thermodynamics-52", "question": "The heat measured in a bomb calorimeter (rigid, sealed vessel) for a combustion reaction equals:", "options": ["ΔH", "ΔU", "ΔG", "TΔS"], "answer": 1, "explanation": "At constant volume no expansion work is done, so q_v = ΔU. ΔH is obtained afterwards from ΔH = ΔU + Δn(g)RT; a coffee-cup calorimeter at constant pressure gives ΔH directly.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-53", "question": "For a reaction at 298 K, ΔH = −50 kJ and ΔS = −100 J K⁻¹. The maximum non-expansion (useful) work obtainable from it is about:", "options": ["50 kJ", "79.8 kJ", "20.2 kJ", "29.8 kJ"], "answer": 2, "explanation": "Maximum useful work = −ΔG. ΔG = ΔH − TΔS = −50 − 298(−0.100) = −50 + 29.8 = −20.2 kJ, so 20.2 kJ can be obtained. Taking −ΔH (50 kJ) ignores the entropy cost.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-54", "question": "An ideal gas expands from volume V₁ to V₂ (a) isothermally and reversibly and (b) adiabatically and reversibly, starting from the same state. Which statement is correct?", "options": ["The adiabatic expansion does more work because no heat is lost", "The isothermal expansion does more work, because its pressure stays higher throughout", "Both do the same work because the volume change is the same", "The isothermal expansion does no work because ΔU = 0"], "answer": 1, "explanation": "On a P–V diagram the adiabat falls more steeply than the isotherm (the gas cools), so for the same ΔV the area under the isotherm is larger. Isothermal work comes from heat absorbed; adiabatic work comes from internal energy.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-55", "question": "Using bond enthalpies C=C = 614, C–C = 348, H–H = 436 and C–H = 412 kJ mol⁻¹, the enthalpy change for C₂H₄(g) + H₂(g) → C₂H₆(g) is:", "options": ["+122 kJ mol⁻¹", "−224 kJ mol⁻¹", "−286 kJ mol⁻¹", "−122 kJ mol⁻¹"], "answer": 3, "explanation": "Bonds broken: C=C + H–H = 614 + 436 = 1050 kJ. Bonds formed: C–C + 2 C–H = 348 + 824 = 1172 kJ. ΔH = 1050 − 1172 = −122 kJ mol⁻¹ (the four C–H bonds of ethene are unchanged).", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-56", "question": "Using standard molar entropies N₂(g) = 191.6, H₂(g) = 130.7 and NH₃(g) = 192.5 J K⁻¹ mol⁻¹, ΔS° for N₂(g) + 3H₂(g) → 2NH₃(g) is:", "options": ["−198.7 J K⁻¹", "+198.7 J K⁻¹", "−129.8 J K⁻¹", "−389.9 J K⁻¹"], "answer": 0, "explanation": "ΔS° = 2(192.5) − [191.6 + 3(130.7)] = 385.0 − 583.7 = −198.7 J K⁻¹. It is negative because 4 mol of gas become 2. −129.8 ignores the stoichiometric coefficients.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-57", "question": "For the vaporisation of a pure liquid at its normal boiling point (1 atm), which statement is correct?", "options": ["ΔG < 0 and ΔS = 0", "ΔH = 0 and ΔG = 0", "ΔG = 0 and ΔS = ΔH/T", "ΔG > 0 and ΔH < 0"], "answer": 2, "explanation": "At the normal boiling point liquid and vapour are in equilibrium at 1 atm, so ΔG = 0, giving ΔH = TΔS, i.e. ΔS = ΔH/T. ΔH(vap) is positive, not zero.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-58", "question": "One mole of an ideal gas at 300 K expands isothermally from 10 atm to 1 atm against a constant external pressure of 1 atm. The work done on the gas is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["−5.74 kJ", "−0.25 kJ", "−2.24 kJ", "−2.49 kJ"], "answer": 2, "explanation": "w = −p_ext(V₂ − V₁) = −1 × (RT/1 − RT/10) = −0.9RT = −0.9 × 8.314 × 300 = −2245 J ≈ −2.24 kJ. −5.74 kJ (= −2.303RT log 10) would be the reversible work, the maximum possible.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-59", "question": "100 mL of 0.5 M HCl is mixed with 100 mL of 0.5 M NaOH, both at the same initial temperature. Taking the enthalpy of neutralisation as −57.1 kJ mol⁻¹, the solution's specific heat as 4.18 J g⁻¹ K⁻¹ and its density as 1 g mL⁻¹, and ignoring heat losses, the rise in temperature is about:", "options": ["3.4 K", "6.8 K", "1.7 K", "0.34 K"], "answer": 0, "explanation": "Water formed = 0.05 mol, heat released = 0.05 × 57 100 = 2855 J. Mass of solution = 200 g, so ΔT = 2855/(200 × 4.18) = 3.4 K. Using only 100 g of solution gives 6.8 K.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-60", "question": "How many of the following statements are correct? (A) The standard enthalpy of formation of O₃(g) is not zero. (B) The standard enthalpy of formation of C(diamond) is zero. (C) The standard enthalpy of formation of Br₂(l) is zero. (D) By convention, the standard enthalpy of formation of H⁺(aq) is taken as zero.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "ΔfH° is zero only for an element in its reference (most stable) form: O₂, not O₃; graphite, not diamond (+1.9 kJ mol⁻¹); and liquid bromine. H⁺(aq) is assigned zero as the reference for ions. So A, C and D are correct: three.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-61", "question": "A diatomic ideal gas (γ = 1.4) at 300 K is compressed adiabatically and reversibly to 1/32 of its original volume. The final temperature is:", "options": ["600 K", "1200 K", "3024 K", "9600 K"], "answer": 1, "explanation": "TV^(γ−1) is constant: T₂ = 300 × 32^0.4 = 300 × 2^(5 × 0.4) = 300 × 2² = 1200 K. Using γ = 5/3 (monoatomic) would give 300 × 32^(2/3) ≈ 3024 K.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-thermodynamics-62", "question": "For a reaction, ΔG° (in kJ mol⁻¹) varies with temperature as ΔG° = 50 − 0.1T, where T is in kelvin. ΔH°, ΔS° and the temperature above which the reaction becomes spontaneous under standard conditions are:", "options": ["+50 kJ, −100 J K⁻¹, 500 K", "−50 kJ, +100 J K⁻¹, 500 K", "+50 kJ, +100 J K⁻¹, 500 K", "+50 kJ, +100 J K⁻¹, 0.5 K"], "answer": 2, "explanation": "Comparing with ΔG° = ΔH° − TΔS°: ΔH° = +50 kJ and ΔS° = +0.1 kJ K⁻¹ = +100 J K⁻¹. ΔG° < 0 when T > 50/0.1 = 500 K. 0.5 K comes from mixing kJ and J.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-63", "question": "Assertion (A): For reactions involving only solids and liquids, ΔH and ΔU are almost equal, whereas they can differ noticeably when gases are formed or consumed. Reason (R): The volume change, and hence the PΔV term, is very small for condensed phases.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "ΔH = ΔU + PΔV. Solids and liquids barely change volume, so PΔV ≈ 0; for gases PΔV = Δn(g)RT, which is several kJ per mole of gas. R correctly explains A.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-64", "question": "Match the reaction (Column I) with ΔH − ΔU for it at temperature T (Column II). (a) C(s) + O₂(g) → CO₂(g); (b) 2C(s) + O₂(g) → 2CO(g); (c) N₂(g) + 3H₂(g) → 2NH₃(g); (d) H₂(g) + ½O₂(g) → H₂O(l). (1) −2RT; (2) −3/2 RT; (3) 0; (4) +RT.", "options": ["a-1, b-4, c-3, d-2", "a-3, b-2, c-1, d-4", "a-3, b-4, c-2, d-1", "a-3, b-4, c-1, d-2"], "answer": 3, "explanation": "ΔH − ΔU = Δn(g)RT. (a) 1 − 1 = 0; (b) 2 − 1 = +1; (c) 2 − 4 = −2; (d) 0 − 1.5 = −1.5 (liquid water is not counted). So a-3, b-4, c-1, d-2.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-65", "question": "1 mol of ice at 273 K is melted, the water is heated to 373 K and then completely vaporised at 373 K. Given ΔfusH = 6.0 kJ mol⁻¹, ΔvapH = 40.7 kJ mol⁻¹, Cp(water) = 75.3 J K⁻¹ mol⁻¹ and ln(373/273) = 0.312, the total entropy change is about:", "options": ["131.1 J K⁻¹", "154.6 J K⁻¹", "109.1 J K⁻¹", "177.0 J K⁻¹"], "answer": 1, "explanation": "ΔS = 6000/273 + 75.3 × 0.312 + 40 700/373 = 21.98 + 23.49 + 109.12 = 154.6 J K⁻¹. 131.1 leaves out the heating step.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-66", "question": "How many of the following statements are correct? (A) All exothermic reactions are spontaneous. (B) An endothermic reaction can be spontaneous if TΔS is greater than ΔH. (C) A spontaneous process is always fast. (D) For a process at equilibrium at constant T and P, ΔG = 0.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(B) and (D) are correct. (A) is false; an exothermic reaction with ΔS < 0 becomes non-spontaneous at high T. (C) is false; spontaneity says nothing about rate (diamond → graphite is spontaneous but extremely slow). Two are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-67", "question": "1 mol of an ideal gas at 300 K expands isothermally in two stages: first from 4 atm to 2 atm against a constant external pressure of 2 atm, then from 2 atm to 1 atm against a constant external pressure of 1 atm. The total work done on the gas is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["−1.87 kJ", "−3.46 kJ", "−4.99 kJ", "−2.49 kJ"], "answer": 3, "explanation": "Stage 1: −2(RT/2 − RT/4) = −RT/2. Stage 2: −1(RT − RT/2) = −RT/2. Total = −RT = −8.314 × 300 = −2494 J ≈ −2.49 kJ. A single stage against 1 atm gives −0.75RT (−1.87 kJ) and the reversible path −RT ln 4 (−3.46 kJ): more stages bring the work closer to the reversible limit.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-thermodynamics-68", "question": "Assertion (A): No heat is absorbed when an ideal gas expands isothermally and reversibly. Reason (R): ΔU = 0 for an isothermal process of an ideal gas.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true because U of an ideal gas depends only on T. A is false: since ΔU = 0, q = −w = nRT ln(V₂/V₁), which is positive for expansion. Heat is absorbed and all of it is converted into work.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-thermodynamics-69", "question": "Which of the following quantities is NOT fixed by the initial and final states alone (i.e. is not a state function or equal to the change in one)?", "options": ["q for an isothermal process", "q + w", "q at constant volume", "w for an adiabatic process"], "answer": 0, "explanation": "q + w = ΔU, q at constant volume = ΔU, and w(adiabatic) = ΔU, so each is fixed by the end states. Heat in an isothermal process depends on the path (reversible versus irreversible expansion between the same states absorb different heat).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-thermodynamics-70", "question": "Given ΔfH°: NO(g) = +90 kJ mol⁻¹ and NO₂(g) = +33 kJ mol⁻¹, ΔU for 2NO(g) + O₂(g) → 2NO₂(g) at 298 K is about (RT = 2.48 kJ mol⁻¹):", "options": ["−116.5 kJ", "−114.0 kJ", "−111.5 kJ", "−57.0 kJ"], "answer": 2, "explanation": "ΔH = 2(33) − 2(90) = −114 kJ. Δn(g) = 2 − 3 = −1, so ΔU = ΔH − Δn(g)RT = −114 + 2.48 = −111.5 kJ. −116.5 kJ uses the wrong sign for the correction; −114.0 kJ is ΔH itself.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-thermodynamics-71", "question": "Which of the following is the correct order of standard molar entropy at 298 K?", "options": ["C(diamond) < C(graphite) < H₂O(l) < CO₂(g)", "C(graphite) < C(diamond) < H₂O(l) < CO₂(g)", "C(diamond) < H₂O(l) < C(graphite) < CO₂(g)", "H₂O(l) < C(diamond) < C(graphite) < CO₂(g)"], "answer": 0, "explanation": "S° (J K⁻¹ mol⁻¹): diamond 2.4 (rigid 3-D network), graphite 5.7 (layers can vibrate more freely), H₂O(l) 69.9, CO₂(g) 213.7. Gases ≫ liquids ≫ solids, and the stiffer diamond lattice has the lowest entropy.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-72", "question": "An ideal gas is taken through a complete cycle and returned to its initial state. Which statement is necessarily true?", "options": ["q = 0 and w = 0", "ΔU = 0, but q and w need not be zero", "ΔU = q", "q = 0, but ΔU and w need not be zero"], "answer": 1, "explanation": "U is a state function, so its change over any cycle is zero (likewise ΔH and ΔS of the gas). Heat and work are path functions; over a cycle q = −w, which is generally non-zero (that is how engines work).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-73", "question": "Given ΔfH°(Al₂O₃, s) = −1676 kJ/mol and ΔfH°(Fe₂O₃, s) = −824 kJ/mol, ΔH° for the thermite reaction 2Al(s) + Fe₂O₃(s) → Al₂O₃(s) + 2Fe(s) is:", "options": ["−2500 kJ", "+852 kJ", "−852 kJ", "−1676 kJ"], "answer": 2, "explanation": "ΔH° = ΣΔfH°(products) − ΣΔfH°(reactants) = (−1676 + 0) − (−824 + 0) = −852 kJ. Al and Fe in their standard states have ΔfH° = 0; adding the two values gives the −2500 trap.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-74", "question": "1 mol of N₂ and 1 mol of O₂, each at the same temperature and pressure, are allowed to mix isothermally to form an ideal mixture at the same total pressure. The entropy of mixing is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["5.76 J/K", "0", "23.1 J/K", "11.5 J/K"], "answer": 3, "explanation": "ΔS_mix = −nR Σ xᵢ ln xᵢ = −2R(0.5 ln 0.5 + 0.5 ln 0.5) = 2R ln 2 = 11.5 J/K (each gas doubles its volume). 5.76 J/K counts only one gas, and 0 wrongly uses ΔH_mix = 0 as a reason for no entropy change.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-thermodynamics-75","question":"For N₂(g) + 3H₂(g) → 2NH₃(g), ΔH° = −92.0 kJ at 298 K and ΔCp = −45 J/K (assume constant). ΔH° for the reaction at 398 K is:","options":["−96.5 kJ","−87.5 kJ","−92.0 kJ","−137 kJ"],"answer":0,"explanation":"Kirchhoff's equation: ΔH(T₂) = ΔH(T₁) + ΔCp(T₂ − T₁) = −92.0 + (−45 × 100)/1000 = −96.5 kJ. The sign of ΔCp makes ΔH more negative; using J as kJ gives the absurd −137 kJ.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-76","question":"1 mol of an ideal diatomic gas (vibrations not excited) expands reversibly and adiabatically, its temperature falling from 300 K to 200 K. The work done ON the gas is about:","options":["−2.91 kJ","−2.08 kJ","−1.25 kJ","0"],"answer":1,"explanation":"For an adiabatic process q = 0, so w = ΔU = nCvΔT = 1 × (5/2)(8.314)(−100) = −2078 J ≈ −2.08 kJ (the gas does 2.08 kJ of work). Using Cp (7R/2) gives −2.91 kJ and the monoatomic Cv gives −1.25 kJ.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-thermodynamics-77", "question": "The enthalpies of solution of anhydrous CuSO₄ and of CuSO₄·5H₂O are −66.5 kJ/mol and +11.7 kJ/mol respectively. The enthalpy of hydration CuSO₄(s) + 5H₂O(l) → CuSO₄·5H₂O(s) is:", "options": ["−54.8 kJ/mol", "+78.2 kJ/mol", "−78.2 kJ/mol", "+54.8 kJ/mol"], "answer": 2, "explanation": "Both salts end as the same solution, so by Hess's law ΔH(hydration) = ΔH_soln(anhydrous) − ΔH_soln(hydrate) = −66.5 − 11.7 = −78.2 kJ/mol. Adding the two numbers directly gives −54.8.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-78", "question": "A mixture contains 1 mol of helium and 1 mol of nitrogen (both ideal; vibrations of N₂ not excited). The ratio Cp/Cv of the mixture is:", "options": ["1.53", "1.40", "1.67", "1.50"], "answer": 3, "explanation": "Heat capacities add, not γ values: Cv = (1 × 3R/2 + 1 × 5R/2)/2 = 2R per mole, Cp = Cv + R = 3R, so γ = 3R/2R = 1.50. Averaging γ directly ((1.67 + 1.40)/2) gives the trap 1.53.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id":"chem-thermodynamics-79","question":"For H₂(g) + ½O₂(g) → H₂O(l) at 298 K, ΔH° = −286 kJ/mol and ΔG° = −237 kJ/mol. The maximum (thermodynamic) efficiency of an ideal H₂–O₂ fuel cell at this temperature is about:","options":["83%","100%","17%","62%"],"answer":0,"explanation":"A fuel cell converts at most ΔG into electrical work, while the total energy released as heat in combustion is ΔH. Efficiency = ΔG/ΔH = 237/286 = 0.83. The remaining 17% (−TΔS, because ΔS is negative) must be released as heat.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-80","question":"Using the enthalpies of combustion H₂ −286, CH₄ −890, C₂H₅OH(l) −1367 and C(graphite) −393.5 kJ/mol, which fuel releases the most heat per gram?","options":["CH₄","H₂","C (graphite)","C₂H₅OH"],"answer":1,"explanation":"Per gram: H₂ 286/2 = 143 kJ/g, CH₄ 890/16 = 55.6, C 393.5/12 = 32.8, C₂H₅OH 1367/46 = 29.7 kJ/g. Methane releases the most per mole among these, which is the trap; per gram hydrogen wins easily.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-81","question":"1 mol of a monoatomic ideal gas at 300 K and 1 atm is compressed adiabatically by a constant external pressure of 10 atm until its pressure becomes 10 atm. The final temperature is:","options":["754 K","3000 K","1380 K","600 K"],"answer":2,"explanation":"q = 0, so ΔU = w: (3/2)R(T₂ − 300) = −P_ext(V₂ − V₁) = −10 × R(T₂/10 − 300/1) = −R(T₂ − 3000). Hence 2.5T₂ = 3450 and T₂ = 1380 K. The reversible formula T₂ = 300 × 10^(0.4) = 754 K is the trap; an irreversible compression heats the gas more.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-82","question":"Given ΔfH°(N₂H₄, g) = +95.4 kJ/mol and the bond enthalpies N≡N = 946, H–H = 436 and N–H = 391 kJ/mol, the N–N single bond enthalpy in hydrazine is about:","options":["254 kJ/mol","63 kJ/mol","349 kJ/mol","159 kJ/mol"],"answer":3,"explanation":"N₂(g) + 2H₂(g) → H₂N–NH₂(g): ΔH = Σ(bonds broken) − Σ(bonds formed) = (946 + 2 × 436) − (4 × 391 + x) = 95.4, so x = 1818 − 1564 − 95.4 = 158.6 ≈ 159 kJ/mol. Using −95.4 (wrong sign of ΔfH) gives 349 kJ/mol.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-83","question":"1 mol of supercooled water at 263 K freezes irreversibly to ice at 263 K and 1 atm. Using Cp(water) = 75.3, Cp(ice) = 37.6 J K⁻¹ mol⁻¹ and ΔfusH = 6.00 kJ/mol at 273 K, the total entropy change of the universe is about:","options":["+0.81 J/K","0","−0.60 J/K","−0.81 J/K"],"answer":0,"explanation":"System (reversible path 263 → 273 K water, freeze at 273 K, ice 273 → 263 K): ΔS = 75.3 ln(273/263) − 6000/273 + 37.6 ln(263/273) = −20.57 J/K. Heat released at 263 K: ΔH = −6000 + (37.6 − 75.3)(−10) = −5623 J, so ΔS_surr = +21.38 J/K. ΔS_univ = +0.81 J/K, positive as a spontaneous change must be; 0 would hold only at 273 K.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-thermodynamics-84", "question": "How many of the following statements are correct? (A) The internal energy of an ideal gas depends only on its temperature. (B) For a reversible adiabatic expansion, ΔS of the system is zero. (C) For an irreversible adiabatic expansion, ΔS of the system is also zero because q = 0. (D) The relation Cp − Cv = R holds exactly for one mole of any real gas.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A ✓ and B ✓ (q_rev = 0). C is false: entropy is defined through q_rev, and for an irreversible adiabatic change ΔS_sys > 0 even though the actual q = 0. D is false: Cp − Cv = R is exact only for an ideal gas. Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-85", "question": "2 mol of a monoatomic ideal gas expands isothermally and reversibly at 300 K from 1 L to 10 L, and is then cooled at constant volume to 150 K. The total entropy change of the gas is about (R = 8.314 J K⁻¹ mol⁻¹, ln 10 = 2.303, ln 2 = 0.693):", "options": ["38.3 J/K", "21.0 J/K", "9.3 J/K", "55.6 J/K"], "answer": 1, "explanation": "Step 1: ΔS = nR ln(V₂/V₁) = 2 × 8.314 × 2.303 = 38.3 J/K. Step 2: ΔS = nCv ln(T₂/T₁) = 2 × 12.47 × ln 0.5 = −17.3 J/K. Total = 21.0 J/K. Using Cp for the isochoric step gives 9.3 J/K.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-thermodynamics-86", "question": "1 mol of an ideal gas at 300 K expands isothermally from 2 atm to 1 atm against a constant external pressure of 1 atm. The entropy change of the universe is about (R = 8.314 J K⁻¹ mol⁻¹):", "options": ["0", "5.76 J/K", "1.61 J/K", "−1.61 J/K"], "answer": 2, "explanation": "ΔS_sys = R ln(P₁/P₂) = R ln 2 = 5.76 J/K (state function). Heat actually absorbed = work done = P_ext(V₂ − V₁) = RT(1 − 1/2) = 0.5RT, so ΔS_surr = −0.5R = −4.16 J/K. ΔS_univ = +1.61 J/K; zero would apply only to the reversible path.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-thermodynamics-87","question":"For MgO, given (kJ/mol): ΔfH° = −602, sublimation of Mg = +148, IE₁ + IE₂ of Mg = +2189, ½ bond dissociation of O₂ = +249, first electron gain enthalpy of O = −141 and second electron gain enthalpy of O = +780. The lattice enthalpy of MgO is:","options":["2267 kJ/mol","3225 kJ/mol","4429 kJ/mol","3827 kJ/mol"],"answer":3,"explanation":"Born–Haber: ΔfH = sub + IE + ½D + Δeg₁ + Δeg₂ − U, so −602 = 148 + 2189 + 249 − 141 + 780 − U and U = 3225 + 602 = 3827 kJ/mol. The second electron gain enthalpy is positive (adding e⁻ to O⁻); using −780 gives 2267.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-88","question":"Taking ΔfH°(H⁺, aq) = 0 by convention, ΔfH°(H₂O, l) = −285.8 kJ/mol and the enthalpy of neutralisation of a strong acid by a strong base = −57.3 kJ/mol, the standard enthalpy of formation of OH⁻(aq) is:","options":["−228.5 kJ/mol","−343.1 kJ/mol","+228.5 kJ/mol","−285.8 kJ/mol"],"answer":0,"explanation":"Net neutralisation: H⁺(aq) + OH⁻(aq) → H₂O(l), ΔH = −57.3 = −285.8 − (0 + x), so x = −228.5 kJ/mol. Adding the two numbers gives −343.1, which is the trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-89","question":"1 mol of a monoatomic ideal gas expands at a constant pressure of 2 atm from 10 L to 20 L. The change in its internal energy is about (1 L atm = 101.3 J):","options":["2.03 kJ","3.04 kJ","−2.03 kJ","5.07 kJ"],"answer":1,"explanation":"ΔU = nCvΔT = (3/2)nRΔT = (3/2)PΔV for an isobaric ideal gas = 1.5 × 2 × 10 L atm = 30 L atm = 3.04 kJ. The heat absorbed is ΔH = (5/2)PΔV = 5.07 kJ and the work done by the gas is 2.03 kJ.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-90","question":"Two identical copper blocks, each with heat capacity 100 J/K, one at 400 K and the other at 200 K, are placed in contact in an insulated enclosure until they reach a common temperature. The total entropy change is about:","options":["0","−11.8 J/K","11.8 J/K","40.5 J/K"],"answer":2,"explanation":"Final temperature = 300 K. ΔS = C ln(300/400) + C ln(300/200) = 100 (−0.2877 + 0.4055) = 100 ln(9/8) = 11.8 J/K. Heat lost equals heat gained, but the hot block loses it at higher temperature, so ΔS > 0, not zero.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-91","question":"For 2NO₂(g) ⇌ N₂O₄(g) at 298 K, ΔH° = −57.2 kJ/mol and ΔS° = −175.8 J K⁻¹ mol⁻¹. The equilibrium constant Kp (with pressures in bar) at 298 K is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["0.14","70","1.0","7.0"],"answer":3,"explanation":"ΔG° = ΔH° − TΔS° = −57.2 − 298(−0.1758) = −4.81 kJ/mol. K = e^(−ΔG°/RT) = e^(4810/2478) = e^1.94 ≈ 7.0. 0.14 is the constant for the reverse (dissociation) reaction, obtained by a sign slip.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-92","question":"The enthalpy of combustion of methane is −802 kJ/mol when the water formed is a gas. Given ΔvapH(H₂O) = 44 kJ/mol, the enthalpy of combustion of methane when liquid water is formed is:","options":["−890 kJ/mol","−714 kJ/mol","−846 kJ/mol","−758 kJ/mol"],"answer":0,"explanation":"CH₄ + 2O₂ → CO₂ + 2H₂O: condensing 2 mol of water releases 2 × 44 = 88 kJ more, so ΔcH = −802 − 88 = −890 kJ/mol. Forgetting that 2 mol of water form gives −846; adding the condensation the wrong way gives −714.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "chem-thermodynamics-93", "question": "How many of the following statements are correct? (A) q + w is a state function even though q and w separately are not. (B) In an adiabatic process, ΔU = w. (C) The heat exchanged at constant pressure (with only PV work) depends only on the initial and final states. (D) The work done in the free expansion of an ideal gas into a vacuum is zero only if the expansion is isothermal.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A ✓ (q + w = ΔU), B ✓ (q = 0), C ✓ (q_p = ΔH). D is false: in a free expansion P_ext = 0, so w = 0 whatever happens to the temperature. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-thermodynamics-94","question":"A monoatomic ideal gas expands reversibly and adiabatically until its absolute temperature is halved. Its pressure becomes:","options":["1/2 of the original","1/5.66 of the original","1/4 of the original","1/3.17 of the original"],"answer":1,"explanation":"For a reversible adiabatic process P^(1−γ)T^γ = constant, i.e. P ∝ T^(γ/(γ−1)). With γ = 5/3, γ/(γ − 1) = 5/2, so P₂/P₁ = (1/2)^2.5 = 1/5.66. 1/3.17 = (1/2)^(5/3) comes from using γ itself as the exponent.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-thermodynamics-95", "question": "The enthalpy of vaporisation of water at 373 K and 1 atm is 40.7 kJ/mol. Treating the vapour as ideal and neglecting the volume of the liquid, ΔU for the vaporisation of 1 mol of water at 373 K is about:", "options": ["43.8 kJ/mol", "40.7 kJ/mol", "37.6 kJ/mol", "39.9 kJ/mol"], "answer": 2, "explanation": "ΔH = ΔU + Δn_g RT with Δn_g = 1, so ΔU = 40.7 − (8.314 × 373)/1000 = 40.7 − 3.10 = 37.6 kJ/mol. Part of the absorbed heat is spent pushing back the atmosphere; adding RT instead gives 43.8.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-thermodynamics-96","question":"For a process carried out at constant volume with no work other than pressure–volume work, the heat absorbed by the system is equal to:","options":["ΔH","ΔU","ΔG","TΔS"],"answer":1,"explanation":"From the first law, ΔU = q + w. At constant volume the PV work w = −PΔV is zero, so q_v = ΔU. At constant pressure the heat would instead equal ΔH.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-thermodynamics-97","question":"For the reaction 2H₂(g) + O₂(g) → 2H₂O(l), the entropy change of the system is:","options":["Negative, since three moles of gas become a liquid","Zero, since the number of atoms is unchanged","Positive, since water molecules are more complex","Positive, since a bond-forming reaction releases heat"],"answer":0,"explanation":"Three moles of gas are converted into two moles of liquid, so the system becomes far more ordered and ΔS(system) is negative. The reaction is still spontaneous because the large heat release raises the entropy of the surroundings.","difficulty":"easy","source":"NEET"},
  {"id":"chem-thermodynamics-98","question":"For the complete combustion of 1 mol of propane at 298 K, C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l), the value of ΔH − ΔU is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["−14.9 kJ","+7.4 kJ","+2.5 kJ","−7.4 kJ"],"answer":3,"explanation":"Only gases count: Δn_g = 3 − (1 + 5) = −3. ΔH − ΔU = Δn_g RT = −3 × 8.314 × 298 J = −7.4 kJ. Counting the water as vapour would give Δn_g = +1 and +2.5 kJ.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-99","question":"The bond dissociation enthalpy of Cl₂(g) is 242 kJ mol⁻¹. The standard enthalpy of formation of Cl(g) atoms is:","options":["+242 kJ mol⁻¹","−121 kJ mol⁻¹","+121 kJ mol⁻¹","0 kJ mol⁻¹"],"answer":2,"explanation":"The formation reaction of Cl(g) is ½Cl₂(g) → Cl(g), which needs half the bond enthalpy: +121 kJ mol⁻¹. Only Cl₂(g), the reference state, has ΔfH° = 0.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-thermodynamics-100","question":"The standard enthalpy of combustion of graphite is numerically equal to:","options":["The standard enthalpy of formation of CO(g)","The standard enthalpy of formation of CO₂(g)","The enthalpy of sublimation of graphite","The C=O bond enthalpy multiplied by two"],"answer":1,"explanation":"C(graphite) + O₂(g) → CO₂(g) is both the combustion of graphite and the formation reaction of CO₂ from its elements in their standard states, so the two enthalpies are identical (−393.5 kJ mol⁻¹).","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-thermodynamics-101","question":"Given S(s) + O₂(g) → SO₂(g), ΔH° = −297 kJ, and SO₂(g) + ½O₂(g) → SO₃(g), ΔH° = −99 kJ, the standard enthalpy of formation of SO₃(g) is:","options":["−396 kJ mol⁻¹","−495 kJ mol⁻¹","−198 kJ mol⁻¹","+198 kJ mol⁻¹"],"answer":0,"explanation":"Adding the two steps gives S(s) + 3/2O₂(g) → SO₃(g), so ΔfH° = −297 + (−99) = −396 kJ mol⁻¹ (Hess's law). Doubling the second step before adding gives −495 kJ.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-thermodynamics-102","question":"For a process occurring in an isolated system, the criterion for spontaneity is:","options":["ΔH(system) < 0","ΔG(system) < 0 at any temperature","ΔU(system) < 0","ΔS(system) > 0"],"answer":3,"explanation":"An isolated system exchanges neither heat nor work with its surroundings, so ΔU = 0 and ΔS(surroundings) = 0. The second law then requires ΔS(system) = ΔS(universe) > 0. The ΔG < 0 criterion applies to closed systems at constant T and P.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-thermodynamics-103","question":"Using bond enthalpies (kJ mol⁻¹) C–H = 414, Cl–Cl = 243, C–Cl = 330 and H–Cl = 431, ΔH for CH₄(g) + Cl₂(g) → CH₃Cl(g) + HCl(g) is:","options":["−761 kJ","−87 kJ","−104 kJ","+104 kJ"],"answer":2,"explanation":"Bonds broken: one C–H + one Cl–Cl = 657 kJ. Bonds formed: one C–Cl + one H–Cl = 761 kJ. ΔH = 657 − 761 = −104 kJ. Only the bonds that actually change need to be counted; the three spectator C–H bonds cancel.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-104","question":"The standard enthalpy of combustion of ethyne (C₂H₂) is −1300 kJ mol⁻¹. With ΔfH°(CO₂, g) = −393.5 and ΔfH°(H₂O, l) = −285.8 kJ mol⁻¹, ΔfH° of ethyne is about:","options":["+514 kJ mol⁻¹","+227 kJ mol⁻¹","−227 kJ mol⁻¹","+621 kJ mol⁻¹"],"answer":1,"explanation":"C₂H₂ + 5/2O₂ → 2CO₂ + H₂O(l): −1300 = 2(−393.5) + (−285.8) − ΔfH°(C₂H₂), so ΔfH° = −787 − 285.8 + 1300 = +227 kJ mol⁻¹. Ethyne is an endothermic compound; using 2 mol of water would give −59 kJ.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-105","question":"1.60 g of methane is burnt completely in a bomb calorimeter of heat capacity 10.0 kJ K⁻¹ and the temperature rises by 8.90 K. The enthalpy of combustion of methane at 298 K (water formed as liquid) is about:","options":["−895 kJ mol⁻¹","−890 kJ mol⁻¹","−885 kJ mol⁻¹","−89 kJ mol⁻¹"],"answer":0,"explanation":"Heat released = 10.0 × 8.90 = 89 kJ for 0.1 mol, so ΔU = −890 kJ mol⁻¹ (bomb = constant volume). CH₄ + 2O₂ → CO₂ + 2H₂O(l) has Δn_g = −2, so ΔH = ΔU + Δn_g RT = −890 − 4.96 ≈ −895 kJ mol⁻¹. Reporting ΔU as ΔH gives −890.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-106","question":"1 mol of a monoatomic ideal gas is heated at constant pressure from 300 K to 600 K. The entropy change of the gas is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["+5.8 J K⁻¹","+20.2 J K⁻¹","+8.6 J K⁻¹","+14.4 J K⁻¹"],"answer":3,"explanation":"ΔS = Cp ln(T₂/T₁) = (5/2)R ln 2 = 2.5 × 8.314 × 0.693 = 14.4 J K⁻¹. Using Cv (3/2 R) gives 8.6 J K⁻¹, which applies only at constant volume.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-107","question":"A non-associated liquid boils at 350 K at 1 atm. Using Trouton's rule (ΔSvap ≈ 88 J K⁻¹ mol⁻¹), its enthalpy of vaporisation is estimated as about:","options":["3.98 kJ mol⁻¹","88 kJ mol⁻¹","30.8 kJ mol⁻¹","251 kJ mol⁻¹"],"answer":2,"explanation":"At the normal boiling point ΔG = 0, so ΔHvap = Tb·ΔSvap ≈ 350 × 88 = 30,800 J ≈ 30.8 kJ mol⁻¹. Dividing instead of multiplying gives the meaningless 3.98. Hydrogen-bonded liquids (water, ethanol) deviate upwards from this rule.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-108","question":"For KCl(s), given (kJ mol⁻¹): ΔfH° = −437, sublimation of K = +89, first ionisation enthalpy of K = +419, ½ bond enthalpy of Cl₂ = +122 and electron gain enthalpy of Cl = −349. The lattice enthalpy of KCl (for KCl(s) → K⁺(g) + Cl⁻(g)) is:","options":["+156 kJ mol⁻¹","+718 kJ mol⁻¹","+840 kJ mol⁻¹","+1416 kJ mol⁻¹"],"answer":1,"explanation":"Born–Haber: ΔfH° = sub + IE + ½D + Δ_egH − U_lattice, so −437 = 89 + 419 + 122 − 349 − U, giving U = 281 + 437 = 718 kJ mol⁻¹. Using the full Cl–Cl bond enthalpy (244) gives 840.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-109","question":"Standard molar entropies (J K⁻¹ mol⁻¹): SO₂(g) = 248, O₂(g) = 205, SO₃(g) = 257. ΔS° for 2SO₂(g) + O₂(g) → 2SO₃(g) is:","options":["−187 J K⁻¹","+187 J K⁻¹","−205 J K⁻¹","−196 J K⁻¹"],"answer":0,"explanation":"ΔS° = 2(257) − [2(248) + 205] = 514 − 701 = −187 J K⁻¹. The negative value fits the decrease from 3 to 2 moles of gas. Forgetting the stoichiometric coefficients gives −196.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-110","question":"2 mol of an ideal diatomic gas (vibrations not excited) is heated at constant volume from 300 K to 400 K. The heat absorbed is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["1.66 kJ","5.82 kJ","2.49 kJ","4.16 kJ"],"answer":3,"explanation":"At constant volume q = nCvΔT with Cv = (5/2)R for a diatomic gas: q = 2 × 2.5 × 8.314 × 100 = 4157 J ≈ 4.16 kJ. Using Cp (7/2 R) gives 5.82 kJ and using the monoatomic Cv gives 2.49 kJ.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-111","question":"A reaction has ΔH° = −120 kJ mol⁻¹ and ΔS° = −250 J K⁻¹ mol⁻¹ (assume both constant). Which statement is correct?","options":["It is spontaneous above 480 K and non-spontaneous below it","It is spontaneous at all temperatures","It is spontaneous below 480 K and non-spontaneous above it","It is spontaneous below 0.48 K only"],"answer":2,"explanation":"ΔG° = 0 at T = ΔH°/ΔS° = 120000/250 = 480 K. With both ΔH and ΔS negative, ΔG is negative only while |ΔH| > T|ΔS|, i.e. below 480 K. 0.48 K comes from not converting kJ to J.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-112","question":"200 mL of 0.1 M H₂SO₄ is mixed with 200 mL of 0.1 M KOH. If the enthalpy of neutralisation of a strong acid by a strong base is −57.1 kJ per mol of water, the heat evolved is about:","options":["0.57 kJ","1.14 kJ","11.4 kJ","2.28 kJ"],"answer":1,"explanation":"H⁺ = 200 × 0.1 × 2 = 40 mmol, OH⁻ = 20 mmol. Only 20 mmol of water forms (OH⁻ is limiting), so heat = 0.020 × 57.1 = 1.14 kJ. Taking the 40 mmol of H⁺ as the amount neutralised gives 2.28 kJ.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-113","question":"ΔfH°(NH₃, g) = −46 kJ mol⁻¹. The bond enthalpies of N≡N and H–H are 946 and 436 kJ mol⁻¹. The average N–H bond enthalpy in NH₃ is:","options":["391 kJ mol⁻¹","1173 kJ mol⁻¹","376 kJ mol⁻¹","406 kJ mol⁻¹"],"answer":0,"explanation":"½N₂ + 3/2H₂ → NH₃: −46 = (473 + 654) − 3E(N–H). So 3E(N–H) = 1127 + 46 = 1173 and E(N–H) = 391 kJ mol⁻¹. Using +46 instead of −46 gives 376; 1173 is the total for three bonds.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-114","question":"1 mol of zinc dissolves completely in excess dilute HCl in an open beaker at 300 K and 1 atm. The work done by the system as the H₂ produced pushes back the atmosphere is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["+2.49 kJ (work done on the system)","0, as the volume of the solution does not change","−4.99 kJ (work done by the system)","−2.49 kJ (work done by the system)"],"answer":3,"explanation":"1 mol H₂ is produced; w = −PΔV = −Δn_g RT = −1 × 8.314 × 300 J ≈ −2.49 kJ. The gas does work on the surroundings, so w is negative in the IUPAC convention. Taking 2 mol of gas (from 2HCl) doubles the answer wrongly.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-115","question":"A reaction has ΔH° = +150 kJ mol⁻¹ and ΔG° = 0 at 1000 K. Assuming ΔH° and ΔS° are independent of temperature, its equilibrium constant at 1200 K is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["1","0.05","20","1.4 × 10³"],"answer":2,"explanation":"ΔG° = 0 at 1000 K gives ΔS° = 150000/1000 = 150 J K⁻¹ mol⁻¹. At 1200 K, ΔG° = 150 − 1200 × 0.150 = −30 kJ mol⁻¹, so K = exp(30000/(8.314 × 1200)) = e^3.0 ≈ 20. A sign error gives 0.05.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-116","question":"1 mol of an ideal gas is compressed isothermally and reversibly at 300 K from 1 bar to 10 bar. The change in its Gibbs energy is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["0","+5.74 kJ","−5.74 kJ","+2.49 kJ"],"answer":1,"explanation":"At constant T, dG = V dP, so ΔG = nRT ln(P₂/P₁) = 8.314 × 300 × ln 10 = +5.74 kJ. ΔH and ΔU are zero for an isothermal ideal gas, but ΔG is not, because the entropy falls on compression.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-117","question":"For the water-gas shift reaction CO(g) + H₂O(g) ⇌ CO₂(g) + H₂(g) at 298 K, ΔH° = −41.2 kJ mol⁻¹ and ΔS° = −42.1 J K⁻¹ mol⁻¹. The equilibrium constant at 298 K is of the order of:","options":["10⁵","10²","10⁷","10⁻⁵"],"answer":0,"explanation":"ΔG° = −41200 − 298(−42.1) = −28.65 kJ mol⁻¹. K = exp(28650/(8.314 × 298)) = e^11.56 ≈ 1.0 × 10⁵. Ignoring the entropy term would give about 10⁷.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-118","question":"For Ag₂O(s) → 2Ag(s) + ½O₂(g), ΔH° = +31.0 kJ mol⁻¹ and ΔS° = +66.0 J K⁻¹ mol⁻¹. Assuming these values are temperature independent, the lowest temperature at which Ag₂O decomposes under standard conditions is about:","options":["2130 K","47 K","298 K","470 K"],"answer":3,"explanation":"Decomposition becomes spontaneous when ΔG° = ΔH° − TΔS° < 0, i.e. above T = 31000/66.0 ≈ 470 K. This is why silver oxide loses oxygen on gentle heating, unlike most metal oxides.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-119","question":"4.6 g of a mixture of CH₄ and C₂H₆ on complete combustion gives 6.72 L of CO₂ at STP. If the enthalpies of combustion of CH₄ and C₂H₆ are −890 and −1560 kJ mol⁻¹, the heat evolved is:","options":["312 kJ","267 kJ","245 kJ","223 kJ"],"answer":2,"explanation":"Let x mol CH₄ and y mol C₂H₆: 16x + 30y = 4.6 and x + 2y = 0.3 (mol CO₂). Solving gives x = y = 0.1 mol. Heat = 0.1 × 890 + 0.1 × 1560 = 245 kJ.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-120","question":"The enthalpies of hydrogenation of but-1-ene, cis-but-2-ene and trans-but-2-ene to butane are −127, −120 and −116 kJ mol⁻¹. Which conclusion follows?","options":["trans-But-2-ene → cis-but-2-ene has ΔH = −4 kJ mol⁻¹, and the cis isomer is the most stable","cis-But-2-ene → trans-but-2-ene has ΔH = −4 kJ mol⁻¹, and the trans isomer is the most stable of the three","But-1-ene is the most stable since it releases the most heat","All three are equally stable because they give the same product"],"answer":1,"explanation":"All three give the same butane, so the alkene releasing the least heat lies lowest in enthalpy: trans (−116) < cis (−120) < but-1-ene (−127). cis → trans = −120 − (−116) = −4 kJ mol⁻¹, reflecting relief of steric strain and more substituted double bonds being more stable.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-thermodynamics-121","question":"How many of the following statements are correct? (A) For an ideal gas, ΔU = 0 in any isothermal process. (B) In an adiabatic process, ΔU = w. (C) The entropy of the universe increases in every spontaneous process. (D) Heat and work are state functions. (E) For an exothermic reaction, ΔS of the surroundings is positive.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"(A) true: U of an ideal gas depends only on T. (B) true since q = 0. (C) true: second law. (E) true: the surroundings gain heat, so ΔS_surr = −ΔH/T > 0. (D) is false: heat and work are path functions. Four are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-thermodynamics-122","question":"1 mol of an ideal gas at 300 K expands freely into an evacuated vessel (no heat exchange) so that its volume doubles. The total entropy change of the universe is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["+11.5 J K⁻¹","0","−5.76 J K⁻¹","+5.76 J K⁻¹"],"answer":3,"explanation":"Entropy is a state function: for the gas ΔS = R ln 2 = +5.76 J K⁻¹ (same as for a reversible isothermal path). No heat reaches the surroundings, so ΔS_surr = 0 and ΔS_universe = +5.76 J K⁻¹, consistent with an irreversible process. Using q = 0 to conclude ΔS = 0 is the trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-123","question":"ΔfG°(NH₃, g) = −16.5 kJ mol⁻¹ at 298 K. The value of Kp for N₂(g) + 3H₂(g) ⇌ 2NH₃(g) at 298 K is of the order of (R = 8.314 J K⁻¹ mol⁻¹):","options":["10⁵ to 10⁶ (about 6 × 10⁵)","about 7.8 × 10²","about 1","about 1.6 × 10⁻³"],"answer":0,"explanation":"For the equation as written 2 mol NH₃ form, so ΔG° = 2(−16.5) = −33.0 kJ. K = exp(33000/(8.314 × 298)) = e^13.3 ≈ 6 × 10⁵. Forgetting the factor 2 gives ΔG° = −16.5 kJ and K ≈ 7.8 × 10².","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-thermodynamics-124","question":"The vapour pressure of a liquid doubles when the temperature is raised from 300 K to 315 K. Its enthalpy of vaporisation is about (R = 8.314 J K⁻¹ mol⁻¹, ln 2 = 0.693):","options":["3.63 kJ mol⁻¹","36.3 kJ mol⁻¹","72.6 kJ mol⁻¹","15.8 kJ mol⁻¹"],"answer":1,"explanation":"Clausius–Clapeyron: ln(P₂/P₁) = (ΔHvap/R)(1/T₁ − 1/T₂). So ΔHvap = 0.693 × 8.314/(1/300 − 1/315) = 5.763/1.587 × 10⁻⁴ ≈ 36.3 kJ mol⁻¹. Using log₁₀ 2 (0.301) instead of ln 2 gives 15.8 kJ.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-125","question":"For NaBr(s), given (kJ mol⁻¹): ΔfH° = −361, sublimation of Na = +107, ionisation enthalpy of Na = +496, vaporisation of ½Br₂(l) = +15, ½ bond enthalpy of Br₂(g) = +96, lattice enthalpy (NaBr(s) → Na⁺(g) + Br⁻(g)) = +747. The electron gain enthalpy of Br is:","options":["−328 kJ mol⁻¹","+328 kJ mol⁻¹","−313 kJ mol⁻¹","−343 kJ mol⁻¹"],"answer":0,"explanation":"Starting from Br₂(l), the standard state: −361 = 107 + 496 + 15 + 96 + Δ_egH − 747, giving Δ_egH = −361 + 33 = −328 kJ mol⁻¹. Omitting the vaporisation of liquid bromine gives −343.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-thermodynamics-126","question":"Given ΔfH° (kJ mol⁻¹): Fe₂O₃(s) = −824, CO(g) = −110.5, CO₂(g) = −393.5. The enthalpy change for Fe₂O₃(s) + 3CO(g) → 2Fe(s) + 3CO₂(g) is:","options":["+25 kJ","−541 kJ","−283 kJ","−25 kJ"],"answer":3,"explanation":"ΔH° = 3(−393.5) − [(−824) + 3(−110.5)] = −1180.5 + 1155.5 = −25 kJ. Elements (Fe) have ΔfH° = 0. Ignoring the oxide's enthalpy of formation gives −849 kJ.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-127","question":"For a reaction at 300 K, ΔH° = +40 kJ mol⁻¹ and ΔS° = +120 J K⁻¹ mol⁻¹. Its equilibrium constant at 300 K is about (R = 8.314 J K⁻¹ mol⁻¹):","options":["1.0","0.002","0.20","5.0"],"answer":2,"explanation":"ΔG° = 40 − 300 × 0.120 = +4.0 kJ mol⁻¹, so K = exp(−4000/(8.314 × 300)) = e^(−1.60) ≈ 0.20. A positive ΔG° gives K < 1; inverting the sign gives 5.0.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-128","question":"How many of the following have a standard enthalpy of formation of zero at 298 K? O₂(g), O₃(g), Br₂(l), Br₂(g), C(graphite), C(diamond), I₂(s), white phosphorus","options":["3","5","4","6"],"answer":1,"explanation":"ΔfH° = 0 only for an element in its reference state: O₂(g), Br₂(l), C(graphite), I₂(s) and white phosphorus (the conventional reference form, even though red phosphorus is more stable). O₃, Br₂(g) and diamond have non-zero values. So 5.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-thermodynamics-129","question":"1 mol of an ideal gas expands isothermally at 300 K from 1 L to 10 L, (i) reversibly and (ii) in one step against a constant external pressure equal to the final pressure. The ratio of the work done by the gas in (i) to that in (ii) is about:","options":["2.56","1.00","2.30","0.39"],"answer":0,"explanation":"(i) w = RT ln 10 = 2.303RT. (ii) w = P₂(V₂ − V₁) = (RT/10)(9) = 0.9RT. Ratio = 2.303/0.9 = 2.56. A reversible path always extracts the maximum work, so the ratio must exceed 1.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
